import type { RunDetail, RunInputs, ReviewResult, RunScope } from '../api.ts'
import { ReviewPanel } from '../ReviewDetail.tsx'
import { NodeSection } from '../SectionIndex.tsx'
import type { Resource } from '../useResource.ts'
import './review.css'

type DefinitionNode = RunDetail['definition']['nodes'][number]
type SnapshotNode = RunDetail['snapshot']['nodes'][number]

/** The independent review's section: the recorded verdict, its reviewers and their findings (docs/PRD_VIEWER_UX.md 4.7). */
export function ReviewSections({ scope, node, definitionNodes, snapshotNodes, inputs, refreshToken, onNavigate, onOpenRequirement, onOpenFile, onTransport }: {
  scope: RunScope
  node: SnapshotNode
  definitionNodes: DefinitionNode[]
  snapshotNodes: SnapshotNode[]
  inputs: Resource<RunInputs | null>
  refreshToken: number
  onNavigate: (pathname: string) => void
  onOpenRequirement: (nodeId: string, quote: string) => void
  onOpenFile: (nodeId: string, path: string) => void
  /** Called with the served review's transport, which decides the executor wording ("one print job per reviewer"). */
  onTransport: (transport: ReviewResult['reviewer']['transport']) => void
}) {
  return (
    <NodeSection sectionKey="review" title="Review result">
      <ReviewPanel
        scope={scope}
        node={node}
        definitionNodes={definitionNodes}
        snapshotNodes={snapshotNodes}
        inputs={inputs}
        refreshToken={refreshToken}
        onNavigate={onNavigate}
        onOpenRequirement={onOpenRequirement}
        onOpenFile={onOpenFile}
        onTransport={onTransport}
      />
    </NodeSection>
  )
}

 * line, then the Run and Assignment tabs; the Run view holds the fitted graph, the Steps table and Activity. A node page:
 * the one-line run bar, the tabs, the sticky step strip and the node in full width. One clock ticks here while the run can
 * still change; selecting a step moves the focus to its heading, and coming back returns it to the step's row.
 */
export function RunView({ scope, detail, current, selectedNodeId, selectedAttempt = null, tab, refreshToken, pollToken = 0, freshness, onNavigate, onAnnounce }: Props) {
  const { summary, definition, snapshot } = detail
  const clock = useNow(summary.status !== 'succeeded' && summary.status !== 'cancelled')
  const [zone] = useTimeZone()
  const runStart = useTimeReference()
  const snapshotById = new Map(snapshot.nodes.map(node => [node.node_id, node]))
  const selectedDefinition = selectedNodeId === null ? null : definition.nodes.find(node => node.node_id === selectedNodeId) ?? null
  const selectedState = selectedNodeId === null ? null : snapshotById.get(selectedNodeId) ?? null

  const runKey = `${scope.projectId}/${scope.workflowId}/${scope.runId}`
  const loadEvents = useCallback((signal: AbortSignal) => fetchEvents(scope, signal), [scope])
  const { state: events, reload: reloadEvents } = useResource(`events:${runKey}`, loadEvents, refreshToken, pollToken)
  // The inputs are one resource per run; a 404 INPUTS_NOT_FOUND means "not recorded", which loads as null.
  const loadInputs = useCallback((signal: AbortSignal) => orNotRecorded(fetchRunInputs(scope, signal), NOT_RECORDED.inputs), [scope])
  const { state: inputs, reload: reloadInputs } = useResource(`inputs:${runKey}`, loadInputs, refreshToken, pollToken)
  // The recorded review and the lane results are immutable per URI: read once through the run's cache (docs/PRD_VIEWER_UX.md 7).
  const reviewPath = snapshot.nodes.find(node => node.node_id === 'review')?.result_uri ?? null
  const review = useRunReview(scope, reviewPath, String(refreshToken))

  const eventsData = events.status === 'ready' ? events.data : null
  const inputsData = inputs.status === 'ready' ? inputs.data : null
  const reviewData = review.status === 'ready' ? review.data : null
  const uris = useMemo(() => (eventsData === null ? [] : nowResultUris(detail, eventsData)), [detail, eventsData])
  const { results, pending } = useRunResults(scope, uris, String(refreshToken))
  const run: RunData | null = useMemo(
    () => (eventsData === null ? null : { detail, events: eventsData, inputs: inputsData, review: reviewData, results }),
    [detail, eventsData, inputsData, reviewData, results],
  )
  // The banner waits for what its rules read: the inputs, the review and the lane results (`Now.missing`).
  const settled = run !== null && (inputs.status === 'ready' || inputs.status === 'error') && (reviewPath === null || review.status === 'ready' || review.status === 'error') && pending === 0
  const now = useMemo(() => (settled && run ? deriveNow(run) : null), [settled, run])
  const attention = useMemo(() => (run ? deriveAttention(run) : null), [run])
  const lanes = useMemo(() => (run ? laneLines(run) : []), [run])
  // buildTimeline keeps its own cache (PRD 5.1), which deriveNow and laneLines share; the memo only spares the clock ticks
  // its key check. The Steps rows are read on every tick, since a running step's duration grows with the clock.
  const timeline = useMemo(() => (run ? buildTimeline(run) : null), [run])

                  data-testid="finding-task-link"
                  data-lane={lane}
                >
                  Open in the {lane} task
                </AppLink>
              )
            })}
          </>
        )}
      </td>
    </tr>
  )
}

/** A reviewer's own verdict; a reviewer superseded before deciding, still pending, or blocked by the deadline or a rejected file has none. */
function ReviewerVerdict({ verdict }: { verdict: Reviewer['verdict'] }) {
  if (verdict === null) return <span className="projects-muted" data-testid="reviewer-verdict" data-status="none">No verdict</span>
  const approved = verdict === 'approved'
  return (
    <span className={`status-badge ${approved ? 'status-succeeded' : 'status-failed'}`} data-testid="reviewer-verdict" data-status={verdict}>
      <span>{approved ? 'Approved' : 'Blocked'}</span>
    </span>
  )
}

/**
 * One entry per reviewer of the run, in declared order: id, own verdict, how it ended (with its blocking reason), finding
 * counts by severity, its times and how long it took from launch to its accepted file (only when both were recorded).
 */
function ReviewerStrip({ reviewers }: { reviewers: readonly Reviewer[] }) {
  return (
    <section className="evidence-section reviewer-strip" aria-labelledby="review-reviewers-title" data-testid="reviewer-strip" data-count={reviewers.length}>
      <h4 id="review-reviewers-title">Reviewers ({reviewers.length})</h4>
      <ul className="evidence-list reviewer-list">
        {reviewers.map(reviewer => {
          const took = spanBetween(reviewer.launched_at, reviewer.accepted_at)
          return (
            <li key={reviewer.reviewer_id} data-testid="reviewer-entry" data-reviewer={reviewer.reviewer_id} data-status={reviewer.status} data-verdict={reviewer.verdict ?? 'none'}>
              <p>
                <strong data-testid="reviewer-id">{reviewer.reviewer_id}</strong>{' '}
                <ReviewerVerdict verdict={reviewer.verdict} />{' '}
                <span data-testid="reviewer-status">{outcomeWording(reviewer)}</span>
              </p>
              <p className="projects-muted">
                <span data-testid="reviewer-counts">{severityCounts(reviewer.findings)}</span>
                {reviewer.launched_at !== null && <> · launched <Time iso={reviewer.launched_at} seconds /></>}
                {reviewer.accepted_at !== null && <> · file accepted <Time iso={reviewer.accepted_at} seconds /></>}
                {took !== null && <> · <span className="reviewer-duration">took {formatSpan(took)}</span></>}
              </p>
            </li>
          )
        })}
      </ul>
    </section>
  )
}

const UNLISTED_REVIEWER = 'unlisted'

/**

  const waited = worker.questions.reduce((sum, question) => sum + (question.answered_at ? ms(question.answered_at) - ms(question.asked_at) : 0), 0)
  const start = worker.launch.native_started_at ?? worker.launch.launch_requested_at
  return new Date(ms(start) + inputs.automatic.worker_timeout_seconds * 1000 + waited).toISOString()
}

function succeededNow(context: Context): Draft | null {
  if (context.status !== 'succeeded') return null
  const integrated = lastMessage(context, 'integrate')
  const commit = COMMIT.exec(integrated?.event.message ?? '')?.[0] ?? context.run.review?.candidate_commit ?? null
  const branch = context.run.inputs?.source_branch
  const { runStart, runEnd } = context.timeline
  const headline: Text = [commit ? `✓ Integrated ${commit.slice(0, 7)}${branch ? ` into ${branch}` : ''} · no push performed` : '✓ Succeeded · no push performed']
  if (runEnd) headline.push(' · took ', { kind: 'span', ms: ms(runEnd.at) - ms(runStart.at) })
  const review = context.run.review
  if (review) {
    const approvers = review.reviewers.filter(entry => entry.verdict === 'approved').map(entry => entry.reviewer_id)
    const openP2 = review.findings.filter(finding => finding.severity === 'P2' && finding.disposition === 'open').length
    headline.push(` · review approved${approvers.length ? ` by ${approvers.join(' and ')}` : ''}${openP2 ? ` · ${openP2} open P2` : ''}`)
  }
  return {
    situation: 'succeeded', tone: 'succeeded', glyph: '✓', since: runEnd?.at ?? null, headline,
    next: { action: 'none', label: 'Nothing required by the workflow. Merging or pushing is your decision.', runbook: [RUNBOOK.approve], steps: [], caveat: null },
  }
}

    startAt ? { at: startAt, source: 'inferred', note: previousCandidate ? 'start inferred from the previous candidate verdict' : 'start inferred from the end of verification' } : null)
  close(span, row.status as SpanStatus, at(row), row.text)
  span.result_uri = match?.uri ?? null
  spans.push(span)
  closedBy.set(row.event.sequence, span)
  previousCandidate = row.event.occurred_at
}

// Rule 4: a review without events ends at its verdict and starts at the first reviewer launch, else ≈ at the candidate's end.
const reviewStatus = statusOf('review')
if (!spans.some(span => span.node_id === 'review') && reviewStatus !== 'pending' && detail.definition.nodes.some(node => node.node_id === 'review')) {
  const launched = (review?.reviewers ?? []).map(entry => entry.launched_at).filter(value => value !== null).sort()[0]
  const candidateEnd = latestOf(spans.filter(span => span.node_id === 'candidate').map(span => span.end?.at))
  const start: Instant | null = launched ? { at: launched, source: 'review', note: 'first reviewer launch' }
    : candidateEnd ? { at: candidateEnd, source: 'inferred', note: `start inferred from ${labelOf(detail, 'candidate')}; the review records no launch time` } : null
  const span = newSpan('review', null, Math.max(1, review?.attempt ?? 1), start)
  span.status = reviewStatus
  span.result_uri = snapshotNode(detail, 'review')?.result_uri ?? null
  if (review) close(span, reviewStatus, { at: review.reviewed_at, source: 'review' }, reviewOutcome(review))
  spans.push(span)
}
// Rule 4: an approval without an event is ≈ an instant at the integration.
const integrated = spans.find(span => span.node_id === 'integrate' && span.end)
if (!spans.some(span => span.node_id === 'approval') && statusOf('approval') === 'succeeded' && integrated) {
  const instant: Instant = { at: integrated.end!.at, source: 'inferred', note: 'no approval event recorded' }
  const span = newSpan('approval', null, 1, instant)
  close(span, 'succeeded', instant, 'approved · no approval event recorded')
  spans.push(span)
}

const lastReview = spans.filter(span => span.node_id === 'review').at(-1)
if (review && lastReview?.end) lastReview.outcome = reviewOutcome(review)
const runStatus = detail.snapshot.status
const automatic = automaticRun(run, rows)
for (const span of spans) {

/**
 * A run's state for list rows (1.5.0), computed from the files a run detail reads plus each lane's live questions file,
 * with the rules of `triage.ts` the run page uses, so the two agree. `headline` is redacted and at most 160 characters.
 */
export const runActivitySchema = z.strictObject({
  /** The export's `inputs.feature`; null for exports without an inputs section. */
  feature: z.string().min(1).nullable(),
  /** The latest event that is not a controller PID checkpoint (or a later stop receipt or review verdict). */
  last_activity_at: timestamp.nullable(),
  /** A finished run's last non-controller activity; null while the run can still move. */
  finished_at: timestamp.nullable(),
  /** The first failed, paused or awaiting node in definition order, else the first running one. */
  focus: z.strictObject({ node_id: id, label: z.string().min(1), status, since: timestamp.nullable() }).nullable(),
  attention: z.strictObject({ kind: z.enum(ATTENTION_KINDS), node_id: id.nullable(), since: timestamp.nullable() }).nullable(),
  /** Lanes whose question waits on the operator, from each lane's live `<lane>.questions.json` over the export's record. */
  waiting_questions: z.number().int().nonnegative(),
  /** The focus step's label and its last status message, or the in-scope controller row that stopped the run. */
  headline: z.string().min(1).max(160).nullable(),
  /** Only while the run is running or paused and has logged a controller PID; null otherwise. */
  controller: z.enum(CONTROLLER_STATES).nullable(),
})

/**
 * A run directory as the registry's `viewer.expose_run_dir` serves it: home-relative, without `.` or `..` segments, and made
 * of characters a shell takes unquoted, so `RUN=<run_dir>` pastes as is. The server serves null for any other path.
 */
export const RUN_DIR_PATTERN = /^~(?!.*\/\.\.?(?:\/|$))\/[A-Za-z0-9._@+/-]+$/

export const runSummarySchema = z.strictObject({
  /** 1.5.0 carries `activity`; 1.0.0 (a server before it, and the viewer's worker-phase mocks) does not. */
  contract_version: z.enum(['1.0.0', '1.5.0']),
  ...scope,
  definition_revision: revision,
  run_id: id,
  status,
  created_at: timestamp,
  updated_at: timestamp,
  activity: runActivitySchema.optional(),
}).superRefine((summary, context) => {
  const issue = (message: string) => context.addIssue({ code: 'custom', message, path: ['activity'] })
  const { activity } = summary
  if ((summary.contract_version === '1.5.0') !== (activity !== undefined)) issue('A summary carries activity exactly when it is 1.5.0')
  if (!activity) return
  if (activity.finished_at !== null && !FINISHED_STATUSES.includes(summary.status)) issue('Only a finished run has a finish time')
  if (activity.controller !== null && !LIVE_STATUSES.includes(summary.status)) issue('The controller is read only while the run is running or paused')
  if ((activity.attention?.kind === 'question') !== (activity.waiting_questions > 0)) issue('Attention is a question exactly when a question waits')
})

export const runDetailSchema = z.strictObject({
  summary: runSummarySchema,
  definition: definitionSchema,
  snapshot: runSnapshotSchema,
  /** 1.5.0: the run directory, `~`-relative, for projects the registry lists in `viewer.expose_run_dir`; null otherwise. */
  run_dir: z.string().regex(RUN_DIR_PATTERN).nullable().optional(),
})

// ---- Review results (1.1.0, finding links 1.2.0, lanes from configuration 1.3.0, parallel reviewers 1.4.0) ----

/**
 * A worker lane ID as the verification policy declares it (`contracts/workflow/verification.schema.json` 1.2.0):

